export const MSME_ONBOARDING_STEPS = [
  { id: 'company', label: 'Company profile', path: '/msme-registration' },
  { id: 'operations', label: 'Operations setup', path: '/operations' },
] as const;

export type MsmeOnboardingStepId = (typeof MSME_ONBOARDING_STEPS)[number]['id'];

export const resolveMsmeOnboardingStepIndex = (pathname: string): number => {
  if (pathname.startsWith('/operations')) {
    return 1;
  }
  if (pathname.startsWith('/msme-registration')) {
    return 0;
  }
  return -1;
};
