import React from 'react';
import { Box, LinearProgress, Step, StepLabel, Stepper, Typography } from '@mui/material';
import { Link as RouterLink, useLocation } from 'react-router-dom';
import {
  MSME_ONBOARDING_STEPS,
  resolveMsmeOnboardingStepIndex,
} from '../../constants/onboardingSteps';

interface OnboardingProgressBarProps {
  /** Override auto-detected step index (0 = company, 1 = operations). */
  activeStep?: number;
  subtitle?: string;
}

export const OnboardingProgressBar: React.FC<OnboardingProgressBarProps> = ({
  activeStep,
  subtitle,
}) => {
  const location = useLocation();
  const resolvedStep = activeStep ?? resolveMsmeOnboardingStepIndex(location.pathname);
  if (resolvedStep < 0) {
    return null;
  }

  const progressPct = Math.round(((resolvedStep + 1) / MSME_ONBOARDING_STEPS.length) * 100);

  return (
    <Box
      sx={{
        mb: 3,
        p: 2,
        borderRadius: 2,
        border: '1px solid',
        borderColor: 'divider',
        bgcolor: 'background.paper',
      }}
    >
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', mb: 1 }}>
        <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
          MSME onboarding
        </Typography>
        <Typography variant="caption" color="text.secondary">
          Step {resolvedStep + 1} of {MSME_ONBOARDING_STEPS.length}
        </Typography>
      </Box>
      {subtitle ? (
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
          {subtitle}
        </Typography>
      ) : null}
      <LinearProgress variant="determinate" value={progressPct} sx={{ mb: 2, borderRadius: 1 }} />
      <Stepper activeStep={resolvedStep} alternativeLabel>
        {MSME_ONBOARDING_STEPS.map((step, index) => (
          <Step key={step.id} completed={index < resolvedStep}>
            <StepLabel
              optional={
                index <= resolvedStep ? (
                  <Typography
                    component={RouterLink}
                    to={step.path}
                    variant="caption"
                    sx={{ textDecoration: 'none', color: 'primary.main' }}
                  >
                    {index < resolvedStep ? 'Edit' : 'Open'}
                  </Typography>
                ) : undefined
              }
            >
              {step.label}
            </StepLabel>
          </Step>
        ))}
      </Stepper>
    </Box>
  );
};
